function gcdValues(nums, queries) {
  const maxValue = nums.reduce((a, b) => Math.max(a, b), 0);
  const freq = new Array(maxValue + 1).fill(0);
  for (const num of nums) {
    freq[num]++;
  }
  const pairs = new Array(maxValue + 1).fill(0);
  for (let g = maxValue; g >= 1; g--) {
    let multiples = 0;
    for (let m = g; m <= maxValue; m += g) {
      multiples += freq[m];
    }
    pairs[g] = multiples * (multiples - 1) / 2;
    for (let m = 2 * g; m <= maxValue; m += g) {
      pairs[g] -= pairs[m];
    }
  }
  const prefix = new Array(maxValue + 1).fill(0);
  for (let g = 1; g <= maxValue; g++) {
    prefix[g] = prefix[g - 1] + pairs[g];
  }
  const answer = [];
  for (const q of queries) {
    let low = 1;
    let high = maxValue;
    while (low < high) {
      const mid = Math.floor((low + high) / 2);
      if (prefix[mid] > q) {
        high = mid;
      } else {
        low = mid + 1;
      }
    }
    answer.push(low);
  }
  return answer;
}

