function gcdValues(nums, queries) {
  // List the gcd of every pair, sort the list and read off each queried index.
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const all = [];
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) all.push(gcd(nums[i], nums[j]));
  }
  all.sort((a, b) => a - b);
  return queries.map(q => all[q]);
}

