function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 2 + Math.floor(rand() * 9);
  // Numbers built as a common divisor times a factor share gcds above 1; some inputs use plain random values.
  const divisors = [1, 2, 3, 4, 5, 6, 10, 12, 30, 60, 210, 2310];
  const style = rand();
  const value = () => {
    if (style < 0.25) return 1 + Math.floor(rand() * (large ? 50000 : 12));
    const d = divisors[Math.floor(rand() * (large ? divisors.length : 8))];
    const most = large ? Math.floor(50000 / d) : 6;
    return d * (1 + Math.floor(rand() * most));
  };
  const nums = Array.from({ length: n }, value);
  if (!large && rand() < 0.15) nums[0] = 50000;
  const total = n * (n - 1) / 2;
  const count = large ? 2000 : 1 + Math.floor(rand() * 8);
  const queries = Array.from({ length: count }, () => Math.floor(rand() * total));
  queries[0] = rand() < 0.5 ? 0 : total - 1;
  return [nums, queries];
}
